import {positions} from './arena-layout.mjs';
import {ArenaLife} from './arena-life.js';
import {Skeleton} from './rig.js';
// Presentation consumes engine events; it never rolls damage or changes combat rules.
export class CombatDirector {
  constructor(soundEnabled){this.soundEnabled=soundEnabled;this.animations=new Set();this.audio=null;this.generation=0;this.rigs={};this.soundFiles={swing:'sword_swing.ogg',impact:'body_hit.ogg',block:'shield_clang.ogg',victory:'victory_jingle.ogg'};this.step=0;this.ambience=null;}
  layout(){const arena=document.querySelector(".arena");if(!arena)return;const p=Number(document.querySelector(".fighter.player").style.getPropertyValue("--tile")),e=Number(document.querySelector(".fighter.enemy").style.getPropertyValue("--tile"));const xy=positions(arena.clientWidth,p,e);for(const side of ["player","enemy"])this.actor(side)?.style.setProperty("--screen-x",`${xy[side]}px`);}
  mount(){const arena=document.querySelector(".arena");if(arena){this.layout();this.observer=new ResizeObserver(()=>this.layout());this.observer.observe(arena);}const canvas=document.querySelector(".arena-life");if(canvas)this.life=new ArenaLife(canvas,this.reduced);for(const side of ["player","enemy"]){const el=this.sprite(side);if(el?.querySelector('[data-joint]'))this.rigs[side]=new Skeleton(el,this.reduced);}}
  dispose(){this.observer?.disconnect();this.life?.destroy();this.life=null;Object.values(this.rigs).forEach(r=>r.destroy());this.rigs={};this.generation++;for(const a of this.animations)a.cancel();this.animations.clear();}
  get reduced(){return matchMedia('(prefers-reduced-motion: reduce)').matches;}
  actor(side){return document.querySelector(`.actor[data-side="${side}"]`);}
  sprite(side){return this.actor(side)?.querySelector('.combat-sprite');}
  pose(side,n){const sprite=this.sprite(side);if(sprite)sprite.dataset.pose=String(n);this.rigs[side]?.pose(["idle","windup","strike","block","hit","down"][n],n===2?115:180);}
  async wait(ms){await new Promise(r=>setTimeout(r,this.reduced?Math.min(ms,65):ms));}
  async animate(el,frames,options={}){if(!el)return;const a=el.animate(frames,{duration:this.reduced?1:options.duration||250,easing:'cubic-bezier(.22,.7,.25,1)',fill:'forwards',...options,...(this.reduced?{duration:1}:{})});this.animations.add(a);try{await a.finished;}catch{}finally{this.animations.delete(a);a.cancel();}}
  caption(text){const el=document.querySelector('.combat-caption');if(el)el.textContent=text;}
  sync(e){const energy=document.querySelector('#energy-value');if(energy&&e.energy!==undefined){energy.textContent=e.energy;document.querySelectorAll('.energy-pips i').forEach((p,i)=>p.classList.toggle('lit',i<e.energy));}for(const [side,hp]of [['player',e.hp],['enemy',e.foeHp]]){const f=document.querySelector(`.fighter.${side}`);if(!f)continue;const bar=f.querySelector('[role="progressbar"]'),max=Number(bar.getAttribute('aria-valuemax'));bar.setAttribute('aria-valuenow',hp);bar.firstElementChild.style.width=`${hp/max*100}%`;f.querySelector('.name-row span:last-child').textContent=`${hp}/${max}`;}}
  noise(kind){if(!this.soundEnabled())return;try{
    if(!this.ambience){this.ambience=new Audio('./assets/audio/crowd_shouting.ogg');this.ambience.loop=true;this.ambience.volume=.055;this.ambience.play().catch(()=>{});}
    let file=this.soundFiles[kind];if(kind==='step')file=`footstep_0${this.step++%4+1}.ogg`;
    if(file){const sound=new Audio(`./assets/audio/${file}`);sound.volume=kind==='swing'?.48:kind==='step'?.25:kind==='victory'?.55:.62;sound.playbackRate=kind==='impact'?.94+Math.random()*.12:1;sound.play().catch(()=>{});return;}
    this.audio??=new AudioContext();const c=this.audio;c.resume(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.type=kind==='spell'?'sine':'triangle';o.frequency.setValueAtTime(kind==='spell'?220:450,c.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='spell'?740:160,c.currentTime+.23);g.gain.setValueAtTime(.06,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.25);o.start();o.stop(c.currentTime+.26);
  }catch{}}
  point(side){const arena=document.querySelector('.arena').getBoundingClientRect(),r=this.actor(side).getBoundingClientRect();return{x:r.left-arena.left+r.width*.5,y:r.top-arena.top+r.height*.45};}
  float(side,text,type='damage'){const layer=document.querySelector('.combat-fx');if(!layer)return;const p=this.point(side),el=document.createElement('span');el.className=`combat-number ${type}`;el.textContent=text;el.style.left=`${p.x}px`;el.style.top=`${p.y-20}px`;layer.append(el);this.animate(el,[{opacity:0,transform:'translate(-50%,0) scale(.6)'},{opacity:1,transform:'translate(-50%,-16px) scale(1.15)',offset:.2},{opacity:1,offset:.6},{opacity:0,transform:'translate(-50%,-75px) scale(.95)'}],{duration:850}).then(()=>el.remove());}
  burst(side,color,block=false){const layer=document.querySelector('.combat-fx'),p=this.point(side);if(!layer)return;const ring=document.createElement('div');ring.className=block?'impact-ring guard-ring':'impact-ring';ring.style.cssText=`left:${p.x}px;top:${p.y}px;--fx:${color}`;layer.append(ring);this.animate(ring,[{opacity:1,transform:'translate(-50%,-50%) scale(.2)'},{opacity:0,transform:'translate(-50%,-50%) scale(1.8)'}],{duration:320}).then(()=>ring.remove());if(this.reduced)return;for(let i=0;i<10;i++){const dot=document.createElement('i'),angle=i*Math.PI*.2,dist=24+(i%3)*16;dot.className='combat-spark';dot.style.cssText=`left:${p.x}px;top:${p.y}px;background:${color}`;layer.append(dot);this.animate(dot,[{opacity:1,transform:'translate(0,0) scale(1)'},{opacity:0,transform:`translate(${Math.cos(angle)*dist}px,${Math.sin(angle)*dist-12}px) scale(.2)`}],{duration:300+i*17}).then(()=>dot.remove());}}
  async projectile(from,to,color){const layer=document.querySelector('.combat-fx'),a=this.point(from),b=this.point(to),orb=document.createElement('div');orb.className='spell-orb';orb.style.cssText=`left:${a.x}px;top:${a.y}px;--fx:${color}`;layer.append(orb);this.noise('spell');await this.animate(orb,[{transform:'translate(-50%,-50%) scale(.4)',opacity:.2},{transform:`translate(${(b.x-a.x)*.4}px,-35px) scale(1.15)`,opacity:1,offset:.5},{transform:`translate(${b.x-a.x}px,${b.y-a.y}px) scale(.65)`,opacity:1}],{duration:420});orb.remove();}
  async strike(e){const attacker=this.actor(e.actor),defender=this.actor(e.target);if(!attacker||!defender)return;const evaded=e.type==='evade',magic=['drain','venom','poison'].includes(e.move),heavy=['heavy','power'].includes(e.move),color=magic?(e.move==='drain'?'#ec7baf':'#9ce381'):e.guarded?'#97d9ff':'#ffd99a';const sign=e.actor==='player'?1:-1;const ar=attacker.getBoundingClientRect(),dr=defender.getBoundingClientRect();const distance=Math.max(0,Math.abs(dr.left+dr.width/2-ar.left-ar.width/2)-ar.width*.62);this.caption(e.actor==='player'?(e.move==='attack'?'Your strike':({heavy:'Titan Chop',power:'Heavy strike',flurry:'Twin Sunbreak',riposte:'Skillet Return',drain:'Blood Ribbon',venom:'Bog Venom',crown:'Fairy Ring'}[e.move]||'Your move')):'Rival attacks');this.pose(e.actor,1);if(e.guarded)this.pose(e.target,3);
    if(magic){await this.animate(this.sprite(e.actor),[{filter:'brightness(1)'},{filter:'brightness(1.7) saturate(1.6)'},{filter:'brightness(1)'}],{duration:220});this.pose(e.actor,2);await this.projectile(e.actor,e.target,color);}else{this.rigs[e.actor]?.walk(true);await this.animate(attacker,[{transform:'translateX(0)'},{transform:`translateX(${-sign*12}px) rotate(${-sign*5}deg)`,offset:.2},{transform:`translateX(${sign*distance}px) rotate(${sign*4}deg)`}],{duration:heavy?650:520});attacker.style.transform=`translateX(${sign*distance}px)`;this.rigs[e.actor]?.walk(false);this.pose(e.actor,1);await this.wait(heavy?330:180);this.pose(e.actor,2);this.noise('swing');await this.wait(115);}
    this.sync(e);if(!evaded)this.life?.react(heavy?1.7:.7);if(evaded){this.rigs[e.target]?.pose('duck',90);this.float(e.target,'EVADED','blocked');this.noise('swing');}else{this.noise(e.guarded?'block':'impact');this.float(e.target,e.damage?`−${e.damage}`:'BLOCK',e.guarded?'blocked':'damage');this.burst(e.target,color,e.guarded);this.pose(e.target,e.guarded?3:4);}const targetSprite=this.sprite(e.target);const reactions=[this.animate(targetSprite,[{transform:'translateX(0)',filter:'brightness(1)'},{transform:`translateX(${sign*12}px) rotate(${sign*7}deg)`,filter:'brightness(1.6)',offset:.25},{transform:'translateX(0)',filter:'brightness(1)'}],{duration:280})];if(heavy&&!this.reduced)reactions.push(this.animate(document.querySelector('.arena'),[{transform:'translateX(0)'},{transform:'translateX(-4px)'},{transform:'translateX(4px)'},{transform:'translateX(0)'}],{duration:170}));await this.wait(95);await Promise.all(reactions);if(!magic){this.rigs[e.actor]?.walk(true);await this.animate(attacker,[{transform:`translateX(${sign*distance}px)`},{transform:'translateX(0)'}],{duration:420});attacker.style.transform='';this.rigs[e.actor]?.walk(false);}this.pose(e.actor,0);this.pose(e.target,0);await this.wait(110);
  }
  async move(e){const actor=this.actor(e.actor),arena=document.querySelector('.arena');if(!actor)return;const targetPositions=positions(arena.clientWidth,e.playerPos,e.enemyPos);const shift=targetPositions[e.actor]-parseFloat(actor.style.getPropertyValue("--screen-x"));this.caption(e.actor==='enemy'?'Rival advances':e.to>e.from?'Leap forward':'Leap back');if(e.jump){this.rigs[e.actor]?.pose('duck',90);await this.wait(95);this.rigs[e.actor]?.pose('jump',120);this.noise('swing');await this.animate(actor,[{transform:'translate(0,0)'},{transform:`translate(${shift*.5}px,-85px)`,offset:.45},{transform:`translate(${shift}px,0)`}],{duration:620});}else{this.rigs[e.actor]?.walk(true);await this.animate(actor,[{transform:'translateX(0)'},{transform:`translateX(${shift}px)`}],{duration:620});this.rigs[e.actor]?.walk(false);}actor.closest('.fighter').style.setProperty('--tile',e.to);this.layout();const bounds=actor.getBoundingClientRect(),floor=arena.getBoundingClientRect();this.life?.dust(bounds.left-floor.left+bounds.width/2,bounds.bottom-floor.top,e.jump?1.5:.7);this.rigs[e.actor]?.pose('idle',180);this.sync(e);await this.wait(140);}
  async play(events,before){const gen=this.generation;const actions=document.querySelector('.actions');actions?.setAttribute('aria-busy','true');for(const e of events){if(gen!==this.generation)return;if(e.type==='move'){await this.move(e);}else if(e.type==='dodge'){this.pose('player',3);this.caption('Ready to dodge one hit');await this.wait(220);}else if(e.type==='recover'){this.caption('Catching your breath');this.float('player','+3 ENERGY','healing');await this.wait(350);}else if(e.type==='stance'){if(['guard','brace'].includes(e.move)){this.pose('player',3);this.caption(e.move==='brace'?'Ironroot':'Guard raised');this.noise('block');await this.wait(300);}}else if((e.type==='hit'||e.type==='evade')){await this.strike(e);}else if(e.type==='heal'){this.sync(e);if(e.amount){this.float(e.target,`+${e.amount}`,'healing');this.burst(e.target,'#9cdbad');this.noise('heal');await this.wait(240);}}else if(['poison','recoil'].includes(e.type)){this.sync(e);this.float(e.target,`−${e.damage}`,e.type);this.burst(e.target,e.type==='poison'?'#a8de74':'#efae97');await this.wait(320);}else if(e.type==='charge'){this.pose('enemy',1);this.caption('A heavy strike is coming…');await this.animate(this.sprite('enemy'),[{filter:'brightness(1)'},{filter:'brightness(1.6) sepia(.5)'},{filter:'brightness(1)'}],{duration:400});}else if(e.type==='guard'){this.pose('enemy',3);this.caption('Rival holds their guard');await this.wait(350);}else if(e.type==='defeat'){this.life?.react(3);this.pose(e.target,5);this.caption(e.target==='enemy'?'VICTORY':'DEFEATED');await this.animate(this.actor(e.target),[{transform:'translateY(0)',opacity:1},{transform:'translateY(9px)',opacity:.65}],{duration:500});await this.wait(650);}}actions?.removeAttribute('aria-busy');}
}
